import sys
from collections import deque

def turn(direction, x):
    directions = ['R', 'D', 'L', 'U']
    return directions[(directions.index(direction) + x) % 4]

def move(x, y, direction, N, M):
    if direction == 'R':
        return x, min(y + 1, M - 1)
    elif direction == 'D':
        return min(x + 1, N - 1), y
    elif direction == 'L':
        return x, max(y - 1, 0)
    elif direction == 'U':
        return max(x - 1, 0), y

def simulate(N, M, K, T, bacteria, matrix):
    traps = set()
    visited = [[[False] * 4 for _ in range(M)] for _ in range(N)]
    queue = deque()

    for i in range(K):
        X, Y, direction = bacteria[i]
        traps.add((T[0], T[1]))
        queue.append(((X, Y), direction, 0))

    while queue:
        (X, Y), direction, t = queue.popleft()
        if (X, Y) == (T[0], T[1]):
            return t

        x, y = move(X, Y, direction, N, M)
        new_direction = turn(direction, matrix[X-1][Y-1])

        if not visited[x][y][new_direction]:
            visited[x][y][new_direction] = True
            queue.append(((x, y), new_direction, t + 1))

    return -1

