def find_game_duration(N, M, K, X_Y, bacteria):
    X, Y = X_Y
    directions = {'U': (-1, 0), 'R': (0, 1), 'D': (1, 0), 'L': (0, -1)}
    traps = set()

    def get_next_direction(current_dir, X):
        return list(directions.keys())[(list(directions.keys()).index(current_dir) + X) % 4]

    def move(x, y, d):
        dx, dy = directions[d]
        return x + dx, y + dy

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < M

    def simulate():
        positions = {i: (bacteria[i-1][0] - 1, bacteria[i-1][1] - 1, bacteria[i-1][2]) for i in range(1, K+1)}
        visited = set()

        while True:
            new_positions = {}
            for i in range(1, K+1):
                x, y, d = positions[i]
                if (x, y, d) in visited:
                    traps.add((x, y))
                    continue
                visited.add((x, y, d))
                X = bacteria[i-1][3][x][y]
                next_d = get_next_direction(d, X)
                nx, ny = move(x, y, next_d)
                if not is_valid(nx, ny):
                    next_d = (next_d + 1) % 4
                    nx, ny = move(x, y, next_d)
                new_positions[i] = (nx, ny, next_d)
            if len(traps) == K:
                break
            positions = new_positions

        if len(traps) != K:
            return -1

        return max(sum(1 for pos in positions.values() if pos[0] == tx and pos[1] == ty) for tx, ty in traps)

    return simulate()

