from sys import stdin, stdout
from typing import List, Tuple

def get_direction(dx: int, dy: int) -> str:
    if dx == 0 and dy == 1:
        return 'R'
    elif dx == 1 and dy == 0:
        return 'D'
    elif dx == 0 and dy == -1:
        return 'L'
    elif dx == -1 and dy == 0:
        return 'U'
    else:
        raise ValueError("Invalid direction")

def simulate_bacteria(N: int, M: int, K: int, trap_row: int, trap_col: int, bacteria: List[Tuple[int, int, str, List[List[int]]]]) -> int:
    directions = {'R': (0, 1), 'D': (1, 0), 'L': (0, -1), 'U': (-1, 0)}
    visited = set()

    while True:
        alive = False
        for x, y, dir_char, matrix in bacteria:
            if (x, y, dir_char) in visited:
                continue
            alive = True
            dx, dy = directions[dir_char]
            turn_count = matrix[x-1][y-1]
            for _ in range(turn_count):
                dx, dy = -dy, dx
            nx, ny = x + dx, y + dy
            if not (1 <= nx <= N and 1 <= ny <= M):
                dx, dy = -dx, -dy
                nx, ny = x + dx, y + dy
            if nx == trap_row and ny == trap_col:
                return -1
            visited.add((nx, ny, get_direction(dx, dy)))
        if not alive:
            break

    return len(visited)

